import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { FinancialAnalysisReportRow } from '../../../services/analytics/models';
import { formatNumber, formatVnd } from '../../../utils/formatters';
import { exportExcel } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './BaoCaoPhanTichTaiChinhPage.module.css';

const TEST_ID = 'erp-financial-analysis-report';
const PAGE_ID = 'baocao-bao-cao-phan-tich-tai-chinh';
const TITLE = 'Báo cáo phân tích tài chính';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function pad2(n: number): string {
  return String(n).padStart(2, '0');
}

function isoDate(d: Date): string {
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

function currentMonthStartIso(): string {
  const now = new Date();
  return isoDate(new Date(now.getFullYear(), now.getMonth(), 1));
}

function currentMonthEndIso(): string {
  const now = new Date();
  return isoDate(new Date(now.getFullYear(), now.getMonth() + 1, 0));
}

function formatMoneyCell(value: number | null | undefined): string {
  if (value == null) return '';
  return formatVnd(value);
}

function formatCoefficient(value: number | null | undefined): string {
  if (value == null) return '';
  return formatNumber(value);
}

function rowClassName(row: FinancialAnalysisReportRow): string {
  const parts: string[] = [];
  if (row.iscal) parts.push(styles.rowToneFormula);
  if (row.kind) parts.push(styles.rowToneSection);
  if (row.inCk) parts.push(styles.rowBold);
  return parts.join(' ');
}

const BaoCaoPhanTichTaiChinhPage: React.FC = () => {
  const dispatch = useAppDispatch();

  const [fromDate, setFromDate] = useState(currentMonthStartIso);
  const [toDate, setToDate] = useState(currentMonthEndIso);

  const [items, setItems] = useState<FinancialAnalysisReportRow[]>([]);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [captionText, setCaptionText] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim()) {
      setFilterError('Chọn từ ngày');
      dispatchAppToast(dispatch, { message: 'Chọn từ ngày', type: 'error' });
      return;
    }
    if (!toDate.trim()) {
      setFilterError('Chọn đến ngày');
      dispatchAppToast(dispatch, { message: 'Chọn đến ngày', type: 'error' });
      return;
    }
    if (fromDate.trim() > toDate.trim()) {
      setFilterError('Từ ngày phải ≤ đến ngày');
      dispatchAppToast(dispatch, { message: 'Từ ngày phải ≤ đến ngày', type: 'error' });
      return;
    }

    setLoading(true);
    analyticsService
      .getFinancialAnalysisReport({
        fromDate: fromDate.trim(),
        toDate: toDate.trim(),
        pageSize: 0,
      })
      .then(report => {
        setItems(report.items ?? []);
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setCaptionText((report.meta?.captionText || report.meta?.tuNgay || '').trim());
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo phân tích tài chính'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleRefresh = useCallback(() => {
    setFromDate(currentMonthStartIso());
    setToDate(currentMonthEndIso());
    setFilterError('');
  }, []);

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    void exportExcel(
      '/accounting/financial-analysis-report/export-excel',
      {
        fromDate: appliedFrom,
        toDate: appliedTo,
        pageSize: 0,
      },
      `bao-cao-phan-tich-tai-chinh_${appliedFrom}_${appliedTo}.xlsx`,
    ).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    if (!hasViewed) return;
    window.print();
  }, [hasViewed]);

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'export-excel',
        action: 'exportExcel',
        placement: 'left',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: !hasViewed || loading,
        onClick: handleExport,
      },
      {
        id: 'print',
        action: 'print',
        placement: 'left',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: !hasViewed || loading,
        onClick: handlePrint,
      },
    ],
    [handleExport, handlePrint, handleRefresh, hasViewed, loading],
  );

  const subtitle = hasViewed
    ? captionText || `Từ ngày ${appliedFrom} đến ngày ${appliedTo}`
    : '';

  const grid = (
    <div>
      {subtitle ? (
        <div className={styles.subtitle} data-testid={`${TEST_ID}-subtitle`}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed && !loading ? (
        <div className={styles.hint} data-testid={`${TEST_ID}-hint`}>
          Chọn từ ngày–đến ngày và bấm Xem
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Chỉ tiêu</th>
            <th className={reportStyles.colRight}>Hệ số</th>
            <th>DVT</th>
            <th>Cách tính</th>
            <th className={reportStyles.colRight}>Giá trị 1</th>
            <th className={reportStyles.colRight}>Giá trị 2</th>
          </tr>
        </thead>
        <tbody>
          {items.map((row, index) => (
            <tr
              key={`${row.lineCode ?? ''}|${row.sortStt ?? ''}|${index}`}
              className={rowClassName(row)}
              data-testid={`${TEST_ID}-row-${index}`}
              data-line-code={row.lineCode ?? ''}
              data-kind={row.kind ?? ''}
              data-iscal={row.iscal ? '1' : '0'}
              data-in-ck={row.inCk ? '1' : '0'}
            >
              <td>{row.indicatorName}</td>
              <td className={reportStyles.colRight}>{formatCoefficient(row.coefficient)}</td>
              <td>{row.unit ?? ''}</td>
              <td>{row.calcFormula ?? ''}</td>
              <td className={reportStyles.colRight}>{formatMoneyCell(row.value1)}</td>
              <td className={reportStyles.colRight}>{formatMoneyCell(row.value2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {hasViewed && items.length === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-chart-pie' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <Input
                type="date"
                label="Từ ngày"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <Input
                type="date"
                label="Đến ngày"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <Button
              variant="primary"
              onClick={handleView}
              disabled={loading}
              data-testid={`${TEST_ID}-view-btn`}
            >
              Xem
            </Button>
            {filterError ? (
              <div data-testid={`${TEST_ID}-filter-error`}>{filterError}</div>
            ) : null}
          </>
        )}
      >
        {grid}
      </LinPageLayout>
    </div>
  );
};

export default BaoCaoPhanTichTaiChinhPage;
